+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+        assertThat(page).hasURL("http://localhost:8080/contact");
+        name.assertValue("Draft");
+
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About").setExact(true)).click();
+        dialog = new DialogElement(page);
